def solve(g):
    from collections import Counter
    c=Counter(x for r in g for x in r)
    bg=c.most_common(1)[0][0]
    out=[r[:] for r in g]
    for i,r in enumerate(out):
        for j,x in enumerate(r):
            if x!=bg:
                for k in range(j+1,len(r)):
                    out[i][k]=5 if k-j%2==1 else x
                break
    return out
